const PAYLOAD_URL = process.env.PAYLOAD_URL;
const PAYLOAD_API_KEY = process.env.PAYLOAD_API_KEY;

const headers = {
  Authorization: `users API-Key ${PAYLOAD_API_KEY}`,
  Accept: "application/json"
};

const [lessonsResult, componentsResult] = await Promise.all([
  fetch(`${PAYLOAD_URL}/api/lessons?limit=0&depth=0`, { headers })
    .then((response) => response.json()),
  fetch(`${PAYLOAD_URL}/api/components?limit=0&depth=0`, { headers })
    .then((response) => response.json())
]);

const lessons = lessonsResult.docs;
const components = componentsResult.docs;

const byTrack = new Map();
for (const lesson of lessons) {
  byTrack.set(lesson.track, (byTrack.get(lesson.track) ?? 0) + 1);
}

const byStatus = new Map();
for (const component of components) {
  byStatus.set(component.status, (byStatus.get(component.status) ?? 0) + 1);
}

const dayKey = (value) => new Date(value).toISOString().slice(0, 10);
const activity = new Map();
for (const component of components) {
  const day = dayKey(component.createdAt);
  activity.set(day, (activity.get(day) ?? 0) + 1);
}

// The browser receives counts only: no names, descriptions, or code.
export const chartData = {
  lessons: [...byTrack].map(([name, value]) => ({ name, value })),
  statuses: [...byStatus].map(([name, value]) => ({ name, value })),
  activity: [...activity]
    .sort(([left], [right]) => left.localeCompare(right))
    .map(([day, value]) => ({ day, value }))
};
